// Extrair os segmentos do tópico MQTT.
// Formato esperado: wot/{thing}/properties/{property}

const topic = msg.topic;

if (typeof topic !== "string") {
    node.warn("Tópico MQTT inválido: " + String(topic));
    return null;
}

const parts = topic.split("/");

// Esperado: ["wot", thing, "properties", property]
if (parts.length !== 4 || parts[0] !== "wot" || parts[1].length === 0 || parts[2] !== "properties" || parts[3].length === 0) {
    node.warn("Tópico de propriedade fora do padrão: " + topic);
    return null;
}

const thing = parts[1];
const property = parts[3];

// Preservar o tipo do valor recebido sempre que possível.
let value = msg.payload;

// Interpretar payloads JSON recebidos como strings.
// Exemplos: "175" -> número 175 | "\"on\"" -> string "on" | "true" -> booleano true
if (typeof value === "string") {
    try {
        value = JSON.parse(value);
    } catch (err) {
        value = msg.payload; // Se não for JSON válido, manter o texto original.
    }
}

// Construir a observação para MQTTArt.reporting().
const observation = {
    thing: thing,
    property: property,
    value: value
};

// Preparar a chamada REST do CArtAgO.
msg.method = "POST";
msg.url = "http://mas:8080/workspaces/wmqtt/artifacts/mqtt/operations/reporting/execute";
msg.headers = {"content-type": "application/json"};

// O endpoint REST recebe uma lista contendo o argumento da operação, que é uma string JSON.
msg.payload = JSON.stringify([JSON.stringify(observation)]);
return msg;

// Extrair os segmentos do tópico MQTT.
// Formato esperado: wot/{thing}/events/{event}

const topic = msg.topic;

if (typeof topic !== "string") {
    node.warn("Tópico MQTT inválido: " + String(topic));
    return null;
}

const parts = topic.split("/");

// Esperado: ["wot", thing, "events", event]
if (parts.length !== 4 || parts[0] !== "wot" || parts[1].length === 0 || parts[2] !== "events" || parts[3].length === 0) {
    node.warn("Tópico de evento fora do padrão: " + topic);
    return null;
}

const thing = parts[1];
const event = parts[3];

// Preservar o tipo do valor recebido sempre que possível.
let data = msg.payload;

// Interpretar payloads JSON recebidos como strings.
// Exemplos: "175" -> número 175 | "\"on\"" -> string "on" | "true" -> booleano true
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (err) {
        data = msg.payload; // Se não for JSON válido, manter o texto original.
    }
}

// Construir a observação para MQTTArt.monitoring().
const observation = {
    thing: thing,
    event: event,
    data: data
};

// Preparar a chamada REST do CArtAgO.
msg.method = "POST";
msg.url = "http://mas:8080/workspaces/wmqtt/artifacts/mqtt/operations/monitoring/execute";
msg.headers = {"content-type": "application/json"};

// O endpoint REST recebe uma lista contendo o argumento da operação, que é uma string JSON.
msg.payload = JSON.stringify([JSON.stringify(observation)]);
return msg;

msg.method = 'POST';
msg.url = 'http://mas:8080/workspaces/wmqtt/artifacts/mqtt/operations/communication/execute';
msg.headers = {"content-type": "application/json"};
const observation = {
    target: msg.payload.target,
    operation: msg.payload.operation,
    data: msg.payload.data
};
msg.payload = JSON.stringify([JSON.stringify(observation)]);
return msg;

// Normalize observation
// Topico esperado: // wot/{thing}/properties/{property}

const topic = msg.topic;

if (typeof topic !== "string") {
    node.warn("Tópico MQTT inválido.");
    return null;
}

const parts = topic.split("/");

if (parts.length !== 4 || parts[0] !== "wot" || parts[2] !== "properties") {
    node.warn("Tópico fora do padrão de propriedades: " + topic);
    return null;
}

const thingId = parts[1];
const propertyName = parts[3];

// O payload MQTT pode chegar como string ou objeto.
let payload = msg.payload;

if (Buffer.isBuffer(payload)) {
    payload = payload.toString("utf8");
}

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (err) {
        // Mantém como texto quando não for JSON válido.
    }
}

let numericValue = null;
let textValue = null;

// Trata números e valores booleanos.
if (typeof payload === "number" && Number.isFinite(payload)) {
    numericValue = payload;
} else if (typeof payload === "boolean") {
    textValue = String(payload);
} else if (typeof payload === "string") {
    const parsed = payload.trim();

    if (parsed !== "" && Number.isFinite(Number(parsed))) {
        numericValue = Number(parsed);
    } else {
        textValue = payload;
    }
} else if (
    payload !== null &&
    typeof payload === "object"
) {
    // Para payloads estruturados, extrai "value"
    // quando esse campo existir e for numérico.
    if (
        typeof payload.value === "number" &&
        Number.isFinite(payload.value)
    ) {
        numericValue = payload.value;
    } else if (
        typeof payload.value === "string" &&
        payload.value.trim() !== "" &&
        Number.isFinite(Number(payload.value))
    ) {
        numericValue = Number(payload.value);
    } else if (payload.value !== undefined) {
        textValue = String(payload.value);
    }
}

// Mantém o payload original para persistência.
msg.observation = {
    thing_id: thingId,
    property_name: propertyName,
    numeric_value: numericValue,
    text_value: textValue,
    payload: payload,
    topic: topic
};

return msg;

const o = msg.observation;

msg.query = `
    INSERT INTO observations (
        thing_id,
        property_name,
        numeric_value,
        text_value,
        payload,
        topic
    )
    VALUES (
        $1, $2, $3, $4, $5::jsonb, $6
    )
    RETURNING id, observed_at;
`;

msg.params = [
    o.thing_id,
    o.property_name,
    o.numeric_value,
    o.text_value,
    JSON.stringify(o.payload),
    o.topic
];

return msg;

const topic = msg.topic;

if (typeof topic !== "string") {
    node.warn("Tópico MQTT inválido para evento.");
    return null;
}

const parts = topic.split("/");

if (parts.length !== 4 || parts[0] !== "wot" || !parts[1] || parts[2] !== "events" || !parts[3]) {
    node.warn("Tópico de evento inválido: " + topic);
    return null;
}

let payload = msg.payload;

if (Buffer.isBuffer(payload)) {
    payload = payload.toString("utf8");
}

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (err) {
        // Preserva como texto se não for JSON válido.
    }
}

msg.deviceEvent = {
    thing_id: parts[1],
    event_name: parts[3],
    payload: payload,
    topic: topic
};

return msg;

const e = msg.deviceEvent;

if (!e) {
    node.error("Evento normalizado ausente.", msg);
    return null;
}

msg.query = `
    INSERT INTO device_events (
        thing_id,
        event_name,
        payload,
        topic
    )
    VALUES ($1, $2, $3::jsonb, $4)
    RETURNING id, received_at;
`;

msg.params = [
    e.thing_id,
    e.event_name,
    JSON.stringify(e.payload),
    e.topic
];

return msg;

// ============================================================
// Extrai uma ação Jason e prepara sua persistência/publicação.
// Suporta parâmetros atômicos, numéricos e estruturas compostas.
// ============================================================

const payload = msg.payload;

if (typeof payload !== "object" || payload === null || payload.functor !== "action" || !Array.isArray(payload.terms) || payload.terms.length !== 3) {
    node.warn("Ação inválida recebida em /act: " + JSON.stringify(payload));
    return null;
}

// Converte um termo Jason serializado em um valor JavaScript (formato depende da serialização do DummyArt)
function termToValue(term) {
    if (term === null || term === undefined) {
        throw new Error("Termo Jason ausente.");
    }

    // Termo numérico ou outro valor primitivo serializado.
    if (typeof term !== "object") {
        return term;
    }

    // Número, booleano ou string representados por value.
    if (Object.prototype.hasOwnProperty.call(term, "value")) {
        return term.value;
    }

    // Átomo ou estrutura Jason.
    if (typeof term.functor === "string") {
        const terms = Array.isArray(term.terms) ? term.terms : [];

        if (terms.length === 0) {
            return term.functor;
        }

        return {
            functor: term.functor,
            terms: terms.map(termToValue)
        };
    }

    throw new Error("Formato de termo Jason não reconhecido: " + JSON.stringify(term));
}

let thing;
let action;
let input;

try {
    thing = termToValue(payload.terms[0]);
    action = termToValue(payload.terms[1]);
    input = termToValue(payload.terms[2]);
} catch (err) {
    node.warn("Não foi possível interpretar a ação: " + err.message);
    return null;
}

// Para os campos usados na construção do tópico, aceitar somente
// nomes simples. Não aceitar estruturas compostas nesses campos.
if (typeof thing !== "string" || typeof action !== "string" || !/^[A-Za-z0-9_-]+$/.test(thing) || !/^[A-Za-z0-9_-]+$/.test(action)) {
    node.warn("Dispositivo ou ação inválidos.");
    return null;
}

// O parâmetro deve ser serializável em JSON.
if (input === undefined || typeof input === "function" || typeof input === "symbol") {
    node.warn("Parâmetro da ação inválido.");
    return null;
}

// Validar a serialização antes de persistir a solicitação.
let inputJson;

try {
    inputJson = JSON.stringify(input);
    if (inputJson === undefined) {
        throw new Error("Parâmetro não serializável em JSON.");
    }
} catch (err) {
    node.warn("Parâmetro inválido: " + err.message);
    return null;
}

const topic = `wot/${thing}/actions/${action}`;

msg.actionRequest = {
    agent_id: "bob",
    thing_id: thing,
    action_name: action,
    input: input,
    topic: topic,
    mqtt_payload: inputJson
};

// Registrar a solicitação antes de publicar o comando.
// O INSERT retorna o id que será usado na etapa seguinte.
msg.query = `
    INSERT INTO agent_actions (
        agent_id,
        thing_id,
        action_name,
        input,
        status
    )
    VALUES ($1, $2, $3, $4::jsonb, 'requested')
    RETURNING id, requested_at, status;
`;

msg.params = [
    msg.actionRequest.agent_id,
    msg.actionRequest.thing_id,
    msg.actionRequest.action_name,
    inputJson
];

return msg;

// Recuperar a solicitação original.
const action = msg.actionRequest;

// Verificar se os dados foram preservados.
if (!action) {
    node.error("Solicitação de ação não encontrada após o INSERT.", msg);
    return null;
}

// Verificar se o PostgreSQL retornou o registro inserido.
if (!Array.isArray(msg.payload) || msg.payload.length === 0 || msg.payload[0].id === undefined) {
    node.error("O PostgreSQL não confirmou a inserção da ação.", msg);
    return null;
}

// Guardar o identificador do registro.
action.id = msg.payload[0].id;

// Restaurar tópico e payload MQTT.
// O nó PostgreSQL pode ter substituído msg.payload pelo resultado da consulta.
msg.topic = action.topic;
msg.payload = action.mqtt_payload;

// Preservar o identificador para facilitar o diagnóstico.
msg.action_id = action.id;

return msg;

// ============================================================
// Confirmação genérica de ações WoT a partir de propriedades.
// ============================================================

// Configuração dos dispositivos, ações e estados esperados.
// Para adicionar um dispositivo, basta incluir sua configuração.
const actionConfig = {
    device_01: {
        ledState: {
            action: "setLed",
            states: {
                on: "on",
                off: "off"
            }
        }
    },

    device_02: {
        relayState: {
            action: "setRelay",
            states: {
                on: "on",
                off: "off"
            }
        }
    },

    device_03: {
        motorState: {
            action: "setMotor",
            states: {
                start: "start",
                stop: "stop"
            }
        }
    }
};

// Obter a observação normalizada.
const o = msg.observation;

if (!o) {
    return null;
}

// Identificar a configuração correspondente.
const deviceConfig = actionConfig[o.thing_id];

if (!deviceConfig) {
    // Dispositivo sem ações configuradas para confirmação.
    return null;
}

const propertyConfig = deviceConfig[o.property_name];

if (!propertyConfig) {
    // Propriedade que não confirma nenhuma ação configurada.
    return null;
}

// O valor recebido representa o estado publicado pelo dispositivo.
const state = o.payload;

// Encontrar o comando que corresponde ao estado observado.
// Exemplo: motorState = "running" corresponde a setMotor("start").
const matchingInput = Object.entries(propertyConfig.states)
    .find(([expectedState]) => expectedState === state);

if (!matchingInput) {
    node.warn("Estado não configurado para confirmação: " + JSON.stringify({thing_id: o.thing_id, property_name: o.property_name, state: state}));
    return null;
}

const input = matchingInput[1];

// Construir os dados da confirmação.
msg.actionConfirmation = {
    thing_id: o.thing_id,
    action_name: propertyConfig.action,
    input: input,
    property_name: o.property_name,
    state: state,
    topic: o.topic
};

return msg;
